insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-BIO-L1', 'Unit 1 Cells, tissues and organs: Cells: the building blocks of life', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Unicellular", "Multicellular", "Unicellular", "Multicellular"], "tip": "One cell or many?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Nucleus", "Cell membrane", "Chloroplast", "Cell wall", "Mitochondria"], "tip": "Match the job."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Both", "Plant cells only", "Both", "Plant cells only", "Plant cells only"], "tip": "Three extra parts."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["cell wall", "plant"], ["root", "no light", "underground", "dark"]], "tips": ["Where is there no light?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 5, "n": 5, "ans": ["No nucleus, more room for oxygen", "Very long to carry messages", "Tail to swim", "Large surface to absorb water", "Many chloroplasts"], "tip": "Structure fits function."}, {"kind": "choice", "id": "q4_1", "q": "Q6", "max": 5, "n": 5, "ans": ["Organ", "Tissue", "Organ system", "Cell", "Organ"], "tip": "Smallest to largest."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["thin", "peel", "layer", "epidermis"], ["stain", "iodine", "coverslip", "water"], ["lowest", "low power", "focus", "objective"]], "tips": ["Thin, stain, focus."]}]}, "models": {"1": [["Q1", "Bacteria and yeast are single cells; mango trees and humans are multicellular."]], "2": [["Q2", "Nucleus; membrane; chloroplast; cell wall; mitochondria."]], "3": [["Q3", "Nucleus and membrane: both. Cell wall, chloroplast, large vacuole: plant only."], ["Q4", "Only plant cells have a cell wall, so it is a plant cell [1]; it may come from the root, which gets no light so needs no chloroplasts [1]."]], "4": [["Q5", "As listed."], ["Q6", "Organ; tissue; organ system; cell; organ (a leaf is a plant organ)."]], "5": [["Q7", "Peel a thin layer of onion epidermis and lay it flat on a slide [1]; add a drop of iodine stain and lower a coverslip [1]; start with the lowest-power objective and focus, then increase magnification [1]."], ["Q8", "Cell wall for support; chloroplasts for photosynthesis; vacuole to keep the cell firm."]], "6": [["Exit ticket", "Cell wall, chloroplasts, large permanent vacuole."]]}, "labels": {"q3_1": "Q4", "q5_0": "Q7", "q5_1": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Unicellular or multicellular?", "Q2": "Which part of the cell?", "Q3": "Found in plant cells only, or in both?", "Q4": "A student sees a cell with a cell wall but no chloroplasts. Explain why it could still be a plant cell.", "Q5": "Match the cell to its adaptation.", "Q6": "Cell, tissue, organ or organ system?", "Q7": "Describe how to prepare a slide of onion cells and view it under a microscope.", "Q8": "In your book, draw and label a plant cell and an animal cell. Then write one sentence about why the plant cell needs each of its three extra parts."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
