insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-BIO-L2', 'Unit 2 Living things, viruses and classification: Is it alive? Sorting the living world', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 7, "n": 7, "ans": ["Respiration", "Excretion", "Sensitivity", "Reproduction", "Nutrition", "Growth", "Movement"], "tip": "MRS GREN."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["cannot reproduce on their own", "inside a cell", "no respiration", "do not grow", "not cells", "do not feed", "host"], ["reproduce", "copies", "evolve", "genetic material", "change"]], "tips": ["Look at MRS GREN."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["no", "different", "not the same"], ["infertile", "cannot reproduce", "not fertile"]], "tips": ["Fertile offspring?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Earthworm", "Beetle", "Spider", "Millipede"], "tip": "Follow the questions."}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["opinion", "not clear", "depends", "subjective", "different people"], ["measurable", "observable", "yes or no", "clear", "feature", "count"]], "tips": ["Would everyone agree?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["compound", "simple", "toothed", "smooth"], ["mango", "neem", "jacaranda", "hibiscus"], ["neem", "jacaranda", "mango", "hibiscus"]], "tips": ["Choose one feature that splits them 2 : 2."]}]}, "models": {"1": [["Q1", "Respiration; excretion; sensitivity; reproduction; nutrition; growth; movement."]], "2": [["Q2", "They cannot reproduce on their own and do not respire, grow or feed outside a cell [1]; but they do make copies of themselves inside cells and can evolve [1]."]], "3": [["Q3", "No, they are different species [1] because their offspring is infertile [1]."]], "4": [["Q4", "Earthworm; beetle; spider; millipede."], ["Q5", "Different people may disagree about what \"big\" means, so it is an opinion [1]; a key needs clear features that everyone can observe or count [1]."]], "5": [["Q6", "e.g. \"Is the leaf compound (made of many leaflets)?\" [1]; yes → neem and jacaranda [1]; no → mango and hibiscus [1]."], ["Q7", "e.g. \"Does the leaf have a toothed edge?\" yes → neem / hibiscus; no → jacaranda / mango."]], "6": [["Exit ticket", "Movement, respiration, sensitivity, growth, reproduction, excretion, nutrition."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_1": "Q5", "q5_0": "Q6", "q5_1": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which life process?", "Q2": "Give one reason why viruses are usually described as non-living and one reason some scientists disagree.", "Q3": "A horse and a zebra can breed to produce a zorse, which cannot reproduce. Are horses and zebras the same species? Explain.", "Q4": "Use the key above to name the animal.", "Q5": "Explain why \"Is it big?\" is a poor question for a dichotomous key.", "Q6": "Write the first question of a key to separate these four leaves: mango (simple, smooth edge), neem (compound, toothed edge), jacaranda (compound, smooth edge), hibiscus (simple, toothed edge). Then say which leaves go each way.", "Q7": "In your book, finish the key with a second question for each pair of leaves."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.quizzes (id, topic_id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('47b43304-0c92-522b-8f07-fc856c685f43', 'f84bba01-8c5a-5f21-b14e-014118df8978', 'Stage 7 Biology · Unit 2 Living things, viruses and classification · Checkpoint-style questions', 'Checkpoint-style questions for Stage 7 Biology, Unit 2 Living things, viruses and classification (objectives 7Bp.01, 7Bp.02, 7Bp.03, 7Bp.04), written in the style of the Cambridge Lower Secondary Checkpoint papers. 6 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark.', null, 2, true, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, topic_id = excluded.topic_id;
