insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-BIO-L3', 'Unit 3 Decomposers, food chains and food webs: Who eats whom, and who cleans up?', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Producer", "Herbivore", "Predator", "Prey"], "tip": "Follow the arrows."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["dead", "pile up", "waste"], ["nutrient", "mineral", "soil", "recycle"]], "tips": ["What do plants need from soil?"]}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 4, "n": 4, "ans": ["Quickly", "Slowly", "Slowly", "Quickly"], "tip": "Warm, moist, oxygen."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Gazelle", "Grasshopper", "Lion", "Decomposers"], "tip": "Follow arrows."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 1, "pts": [["grass → grasshopper → bird", "grass grasshopper bird", "grasshopper", "decomposer"]], "tips": ["Start with the producer."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["lion+decrease", "lions decrease", "less food", "fewer lions"], ["gazelle+decrease", "more gazelles eaten", "eat more gazelle"], ["grass", "cheetah", "compet"]], "tips": ["Who else do lions eat?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["temperature", "fridge", "warm", "different"], ["same", "size", "type", "moisture", "control"], ["days", "measure", "area", "observe", "record", "how much mould"]], "tips": ["Change one variable."]}]}, "models": {"1": [["Q1", "Grass producer; zebra herbivore and prey; lion predator."]], "2": [["Q2", "Dead material would pile up [1] and nutrients would not be returned to the soil, so plants could not grow [1]."], ["Q3", "Warm and moist: quickly; cold or dry: slowly."]], "3": [["Q4", "Gazelle; grasshopper; lion; decomposers."], ["Q5", "e.g. grass → grasshopper → bird → decomposers [1]."]], "4": [["Q6", "The lions have less food, so their numbers may fall [1]; lions eat more gazelles instead, so gazelles decrease [1]; this also means less food for the cheetahs (or there is more grass) [1]."]], "5": [["Q7", "Put identical pieces of bread at different temperatures, e.g. fridge, room and warm cupboard [1]; keep the type, size and moisture of the bread the same [1]; observe each day and record how much of the surface is covered by mould [1]."]], "6": [["Exit ticket", "Bacteria and fungi."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "In grass → zebra → lion, name:", "Q2": "Explain why a forest would not survive for long without decomposers.", "Q3": "Will food decay quickly or slowly?", "Q4": "Use the savanna web above.", "Q5": "Write one food chain from the web with four organisms.", "Q6": "In the savanna web, a disease kills most of the zebras. Predict what happens to the lions and to the gazelles, and explain.", "Q7": "Plan an investigation to find out whether temperature affects how fast bread goes mouldy."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
