insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('224aa572-3841-55e1-998d-abe5f92c30dd', '13f686bd-34e6-5c59-be2a-de9234d14310', 'Unit 2 Elements, compounds and mixtures: Joined or just mixed?', 'Stage 7 Chemistry · Objectives 7Cm.04, 7Cm.07', '/cks7-chem-2/', 'CKS7-CHEM-L2', 20, 60, 20) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-CHEM-L2', 'Unit 2 Elements, compounds and mixtures: Joined or just mixed?', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["Element", "Compound", "Mixture", "Compound", "Mixture", "Element"], "tip": "Joined or not?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Element", "Compound", "Mixture of elements", "Mixture of an element and a compound"], "tip": "Count the kinds of particle."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["magnet"], ["mixture", "not joined", "not chemically"]], "tips": ["Iron is magnetic."]}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["compound", "chemically joined", "reaction"], ["not magnetic", "different properties", "new substance"]], "tips": ["What happened chemically?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 3, "n": 3, "ans": ["Steel", "Brass", "Bronze"], "tip": "Common alloys."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 1, "pts": [["not chemically joined", "vary", "different amounts", "any amount", "not fixed"]], "tips": ["Joined? Fixed ratio?"]}], "5": [{"kind": "text", "id": "q5_1", "q": "Q8", "max": 2, "pts": [["chemically joined", "bonded", "joined"], ["fixed", "co2", "one carbon", "two oxygen", "different properties"]], "tips": ["Joined in a fixed ratio."]}]}, "models": {"1": [["Q1", "Oxygen, gold: elements; water, CO₂: compounds; air, sea water: mixtures."]], "2": [["Q2", "Element; compound; mixture of elements; mixture of element and compound."]], "3": [["Q3", "Use a magnet to pull out the iron [1]; this works because it is a mixture, so the iron and sulfur are not chemically joined [1]."], ["Q4", "They have reacted to form a compound, so the atoms are chemically joined [1]; iron sulfide has different properties and is not magnetic like iron [1]."]], "4": [["Q5", "Steel; brass; bronze."], ["Q6", "The copper and zinc are not chemically joined and can be in different amounts [1]."]], "5": [["Q7", "(a) identical pairs of the same atoms: element; (b) identical particles of one big and two small atoms: compound; (c) two kinds of pairs mixed: mixture."], ["Q8", "The carbon and oxygen atoms are chemically joined [1] in a fixed ratio (one carbon to two oxygen, CO₂) [1]."]], "6": [["Exit ticket", "A mixture."]]}, "labels": {"q3_0": "Q3", "q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q5_1": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Element, compound or mixture?", "Q2": "Which does the diagram show?", "Q3": "Iron filings and sulfur powder are mixed. Describe how you could separate them and explain why this is possible.", "Q4": "When iron and sulfur are heated, iron sulfide forms. Explain why a magnet can no longer separate them.", "Q5": "Name the alloy.", "Q6": "Explain why brass is a mixture, not a compound.", "Q7": "In your book, draw particle diagrams for (a) oxygen gas, O₂, (b) water, H₂O, (c) air (nitrogen N₂ and oxygen O₂). Label each element, compound or mixture.", "Q8": "Carbon dioxide contains carbon and oxygen. Explain why it is a compound and not a mixture."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
