insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-CHEM-L3', 'Unit 3 States of matter: Particles in solids, liquids and gases', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Solid", "Gas", "Liquid", "Gas"], "tip": "Shape, volume, squash."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Solid", "Gas", "Liquid"], "tip": "Arrangement and movement."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["gas+far apart", "gas+space", "spaces between"], ["liquid+touching", "liquid+close", "no space"]], "tips": ["Spaces."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Melting", "Condensation", "Evaporation", "Freezing", "Sublimation"], "tip": "From → to."}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["energy", "heat", "vibrate more", "faster"], ["break", "slide", "leave fixed", "move past"]], "tips": ["Energy and arrangement."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["evaporat"], ["energy", "faster", "hot"], ["wind", "carried away", "removed", "blow"]], "tips": ["Energy and moving particles away."]}]}, "models": {"1": [["Q1", "Solid; gas; liquid; gas."]], "2": [["Q2", "Solid; gas; liquid."]], "3": [["Q3", "Gas particles are far apart with large spaces, so they can be pushed closer [1]; liquid particles are already touching, so there is no space to push them into [1]."]], "4": [["Q4", "Melting; condensation; evaporation; freezing; sublimation."], ["Q5", "The particles gain energy and vibrate more [1] until they break out of their fixed positions and can slide past each other [1]."]], "5": [["Q6", "Water evaporates from the clothes [1]; in hot weather the particles have more energy so more escape from the liquid [1]; the wind carries water particles away so more can evaporate [1]."]], "6": [["Exit ticket", "Condensation."]]}, "labels": {"q3_0": "Q3", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Solid, liquid or gas?", "Q2": "Which state?", "Q3": "Use the particle model to explain why a gas can be squashed but a liquid cannot.", "Q4": "Name the change of state.", "Q5": "Describe what happens to the particles when ice melts.", "Q6": "Wet clothes dry faster on a hot, windy day. Use the particle model to explain why."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
