insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-CHEM-L4', 'Unit 4 Metals, non-metals and alloys: Choosing materials by their properties', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Chemical", "Physical", "Chemical", "Physical"], "tip": "New substance made?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Non-metal", "Metal", "Metal", "Non-metal"], "tip": "Typical properties."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["conduct"], ["ductile", "wires", "bend", "malleable"]], "tips": ["What does a wire need?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 3, "n": 3, "ans": ["Harder than pure gold", "Does not rust", "Stronger than iron"], "tip": "Property gained."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["layers", "regular", "same size"], ["different size", "carbon atoms", "disrupt", "distort"], ["cannot slide", "harder to slide", "not slide"]], "tips": ["Layers and sizes."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["steel", "aluminium", "copper", "iron", "metal"], ["plastic", "wood", "insulat"], ["conduct", "heat", "burn", "hot"]], "tips": ["Conductor vs insulator."]}]}, "models": {"1": [["Q1", "Rusting and burning are chemical; conducting and boiling point are physical."]], "2": [["Q2", "Non-metal; metal; metal; non-metal."], ["Q3", "Copper is a good electrical conductor [1] and it is ductile, so it can be drawn into wires [1]."]], "3": [["Q4", "Harder; does not rust; stronger."]], "4": [["Q5", "In pure iron the atoms are the same size in regular layers that slide easily [1]; in steel, carbon atoms of a different size disrupt the layers [1], so the layers cannot slide easily and steel is harder [1]."]], "5": [["Q6", "The body: steel or aluminium (a metal) [1]; the handle: plastic or wood [1]; the metal conducts heat to cook the food, but the handle is an insulator so you do not burn your hand [1]."]], "6": [["Exit ticket", "Poor conductors / brittle / dull."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Physical or chemical property?", "Q2": "Metal or non-metal property?", "Q3": "Explain why copper is used for electrical wires. Give two properties.", "Q4": "Why is the alloy used?", "Q5": "Use particles to explain why steel is harder than pure iron.", "Q6": "A cooking pan needs a body and a handle. Suggest a material for each and explain your choices."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
