insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-CHEM-L5', 'Unit 5 Acids, alkalis, pH and neutralisation: Measuring and cancelling acidity', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Acidic", "Neutral", "Alkaline", "Alkaline", "Acidic"], "tip": "Below, at or above 7."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Red", "Yellow", "Green", "Blue", "Purple"], "tip": "Rainbow order."}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 2, "n": 2, "ans": ["Red", "Blue"], "tip": "Acid turns litmus red."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["red", "orange"], ["green", "neutral"]], "tips": ["pH rises."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["acid+alkali"], ["salt+water"]], "tips": [""]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["Antacid tablet", "Lime", "Baking soda", "Vinegar"], "tip": "Opposite cancels."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["water", "shake", "mix", "filter"], ["universal indicator", "indicator", "ph paper", "colour chart"], ["lime", "alkali", "neutralis"]], "tips": ["Test, then treat."]}]}, "models": {"1": [["Q1", "Acidic; neutral; alkaline; alkaline; acidic."]], "2": [["Q2", "Red; yellow; green; blue; purple."], ["Q3", "Red; blue."]], "3": [["Q4", "It starts red (acid) [1] and changes through orange and yellow to green when neutral [1] (and blue/purple with excess alkali)."], ["Q5", "acid + alkali [1] → salt + water [1]."]], "4": [["Q6", "Antacid; lime; baking soda; vinegar."]], "5": [["Q7", "Shake a soil sample with distilled water and let it settle (or filter) [1]; add universal indicator and compare the colour with the chart to find the pH [1]; if acidic, add lime (an alkali) to neutralise it [1]."]], "6": [["Exit ticket", "Green."]]}, "labels": {"q3_0": "Q4", "q3_1": "Q5", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Acidic, neutral or alkaline?", "Q2": "What colour is universal indicator?", "Q3": "What colour does litmus turn?", "Q4": "A student adds sodium hydroxide (an alkali) drop by drop to hydrochloric acid with universal indicator. Describe the colour changes.", "Q5": "Write the general word equation for neutralisation.", "Q6": "What would you use?", "Q7": "A farmer''s maize grows poorly. Describe how to test the soil pH and what to do if it is acidic."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
