insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-CHEM-L7', 'Unit 7 The Earth, air and the water cycle (Earth and Space): Our moving planet, its air and its water', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Crust", "Mantle", "Core"], "tip": "Outside to inside."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Fold mountains", "Rift valley", "Earthquakes"], "tip": "Direction of movement."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Nitrogen", "Oxygen", "Carbon dioxide", "Sulfur dioxide"], "tip": "Percentages."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["public transport", "electric", "cycle", "walk", "fewer cars", "renewable", "trees"], ["less", "fewer", "reduce", "exhaust", "fumes", "carbon"]], "tips": ["Where does pollution come from?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Condensation", "Precipitation", "Evaporation", "Run-off"], "tip": "Follow the cycle."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["sun", "solar", "heat"], ["evaporat", "condens"], ["recycle", "not lost", "same water", "cycle", "returns"]], "tips": ["Energy and recycling."]}]}, "models": {"1": [["Q1", "Crust; mantle; core."]], "2": [["Q2", "Fold mountains; rift valley; earthquakes."]], "3": [["Q3", "Nitrogen; oxygen; carbon dioxide; sulfur dioxide."], ["Q4", "e.g. use electric buses or more public transport [1], so fewer exhaust gases are released [1]."]], "4": [["Q5", "Condensation; precipitation; evaporation; run-off."]], "5": [["Q6", "Energy from the Sun [1] evaporates water, which later condenses and falls as precipitation [1]; the same water is recycled again and again, so none is lost [1]."]], "6": [["Exit ticket", "Nitrogen (about 78%)."]]}, "labels": {"q3_1": "Q4", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which layer?", "Q2": "What forms?", "Q3": "Which gas?", "Q4": "Suggest one way to reduce air pollution in a city and explain how it helps.", "Q5": "Name the process.", "Q6": "Explain how the water cycle is powered and why the total amount of water on Earth stays the same."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
