insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-PHYS-L1', 'Unit 1 Energy changes: Where does the energy go?', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Elastic", "Kinetic", "Gravitational potential", "Thermal", "Chemical"], "tip": "What is stored?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Chemical → kinetic", "Gravitational potential → kinetic", "Kinetic → thermal", "Elastic → kinetic"], "tip": "Start and end stores."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["200"], ["surroundings", "air", "kettle", "sound", "thermal"]], "tips": ["Total in = total out."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["thermal", "heat", "sound"], ["less", "spreads", "dissipat", "not destroyed", "surroundings"]], "tips": ["Where does the energy go?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["oil", "lubricat", "grease"], ["tyre", "pump", "streamline", "bearing"], ["friction", "less heat", "thermal"]], "tips": ["Friction wastes energy."]}]}, "models": {"1": [["Q1", "Elastic; kinetic; gravitational potential; thermal; chemical."]], "2": [["Q2", "As listed."]], "3": [["Q3", "2000 − 1800 = 200 J wasted [1], heating the kettle and the surroundings (and as sound) [1]."]], "4": [["Q4", "At each bounce some energy is transferred to thermal energy and sound [1], which spreads into the surroundings, so less is left in the gravitational store [1]."]], "5": [["Q5", "Oil the chain [1]; pump up the tyres / use smooth bearings [1]; this reduces friction, so less energy is transferred to thermal energy [1]."]], "6": [["Exit ticket", "No: it is transferred to other stores."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which energy store increases?", "Q2": "Main change of energy store?", "Q3": "A kettle takes in 2000 J of electrical energy. 1800 J heats the water. How much energy is wasted, and where does it go?", "Q4": "Explain why a bouncing ball rises lower after each bounce.", "Q5": "Suggest two ways to reduce wasted energy in a bicycle and explain one of them."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
