insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-PHYS-L2', 'Unit 2 Gravity and air resistance: Falling: gravity versus air', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Weaker", "Stronger", "Weaker", "Stronger"], "tip": "Mass and distance."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["700"], ["112"]], "tips": ["W = m × g."]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 1, "pts": [["no", "same", "does not"]], "tips": ["Mass is matter."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["area", "surface"], ["air resistance", "drag"]], "tips": ["Same mass."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["no air", "vacuum", "no atmosphere"], ["no air resistance", "same", "only gravity"]], "tips": ["What is missing on the Moon?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["area", "size", "different"], ["same height", "same mass", "same load", "control"], ["time", "stopwatch", "repeat", "average"]], "tips": ["One variable."]}]}, "models": {"1": [["Q1", "Weaker; stronger; weaker; stronger."]], "2": [["Q2", "Earth: 70 × 10 = 700 N [1]; Moon: 70 × 1.6 = 112 N [1]."], ["Q3", "No: she has the same amount of matter, so her mass is still 70 kg [1]."]], "3": [["Q4", "The flat sheet has a larger surface area [1], so it has more air resistance [1]."]], "4": [["Q5", "The Moon has no air (it is a vacuum) [1], so there is no air resistance and only gravity acts, making both fall at the same rate [1]."]], "5": [["Q6", "Make parachutes of different areas [1]; drop each from the same height with the same mass attached [1]; time the fall with a stopwatch and repeat to find an average [1]."]], "6": [["Exit ticket", "Newtons (N)."]]}, "labels": {"q2_0": "Q2", "q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Stronger or weaker gravity?", "Q2": "An astronaut has a mass of 70 kg. Calculate her weight on Earth (g = 10 N/kg) and on the Moon (g = 1.6 N/kg).", "Q3": "Does her mass change on the Moon? Explain.", "Q4": "Explain why a sheet of paper falls more slowly than the same paper screwed into a ball.", "Q5": "Explain why a hammer and a feather hit the ground at the same time on the Moon.", "Q6": "Plan an investigation into how the area of a parachute affects how long it takes to fall."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
