insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-PHYS-L3', 'Unit 3 Sound and echoes: Vibrations, sound and echoes', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["String", "Air column", "Vocal cords", "Skin"], "tip": "Find the vibrating part."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["quieter", "cannot hear", "silent", "fades"], ["no particles", "vacuum", "no air", "no medium"]], "tips": ["Particles carry sound."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["Fastest", "Middle", "Slowest"], "tip": "Closer particles, faster."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 1, "pts": [["light faster", "light travels faster", "faster than sound"]], "tips": ["Compare speeds."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["340", "there and back", "170 × 2"], ["1"]], "tips": ["Total distance 340 m."]}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["3000", "1500 × 2"], ["1500"]], "tips": ["÷ 2."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["curtain", "carpet", "soft", "panel", "foam"], ["cushion", "curtain", "carpet", "soft", "foam", "panel"], ["absorb", "less reflect", "fewer echo"]], "tips": ["Soft surfaces."]}]}, "models": {"1": [["Q1", "String; air column; vocal cords; skin."]], "2": [["Q2", "The sound gets quieter until it cannot be heard [1] because there are no air particles to pass on the vibrations [1]."]], "3": [["Q3", "Steel fastest; water; air slowest."], ["Q4", "Light travels much faster than sound [1]."]], "4": [["Q5", "The sound travels 170 × 2 = 340 m [1]; time = 340 ÷ 340 = 1 s [1]."], ["Q6", "1500 × 2 = 3000 m there and back [1]; depth = 3000 ÷ 2 = 1500 m [1]."]], "5": [["Q7", "Hang thick curtains [1] and lay carpets or soft panels [1]; soft materials absorb sound instead of reflecting it, so there are fewer echoes [1]."]], "6": [["Exit ticket", "Space is a vacuum, with no particles to vibrate."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "What vibrates to make the sound?", "Q2": "A ringing bell is placed in a jar and the air is pumped out. Describe and explain what you hear.", "Q3": "Put sound speeds in order.", "Q4": "Explain why you see lightning before you hear thunder.", "Q5": "A girl claps 170 m from a cliff. How long until she hears the echo? (speed of sound = 340 m/s)", "Q6": "A ship''s sonar pulse returns after 2 s. Sound travels at 1500 m/s in water. Calculate the depth.", "Q7": "A school hall has bad echoes. Suggest two changes and explain how they help."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
