insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-PHYS-L4', 'Unit 4 Electric circuits: Current in series circuits', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Yes", "No", "No", "No"], "tip": "Complete loop?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Conductor", "Insulator", "Conductor", "Insulator", "Conductor"], "tip": "Metals and graphite conduct."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Cell", "Lamp", "Open switch", "Ammeter"], "tip": "Learn the symbols."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 3, "n": 3, "ans": ["Increases", "Decreases", "Increases"], "tip": "Push vs resistance."}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["0.3"], ["same", "series", "not used up"]], "tips": ["Current is not used up."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["add a cell", "more cells", "new battery", "another cell"], ["current+increase", "more current", "push"]], "tips": ["More push."]}]}, "models": {"1": [["Q1", "Only the complete closed circuit lights the lamp."]], "2": [["Q2", "Copper, graphite, steel conduct; plastic, rubber insulate."]], "3": [["Q3", "Cell; lamp; open switch; ammeter."]], "4": [["Q4", "Increases; decreases; increases."], ["Q5", "0.3 A [1] because current is the same at every point in a series circuit [1]."]], "5": [["Q6", "Add another cell in series [1], which increases the current, so the lamp is brighter [1]."], ["Q7", "All components in one loop, using standard symbols drawn with a ruler."]], "6": [["Exit ticket", "An ammeter."]]}, "labels": {"q4_1": "Q5", "q5_0": "Q6", "q5_1": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Will the lamp light?", "Q2": "Conductor or insulator?", "Q3": "Name the component.", "Q4": "Current increases or decreases?", "Q5": "In a series circuit, ammeter A1 before the lamp reads 0.3 A. What does ammeter A2 after the lamp read? Explain.", "Q6": "A torch with one cell and one lamp is dim. Suggest a change to make it brighter and explain using current.", "Q7": "In your book, draw a circuit diagram with two cells, a switch, two lamps and an ammeter in series."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
