insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-PHYS-L5', 'Unit 5 The Solar System, tides and eclipses (Earth and Space): Gravity, tides and shadows in space', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Rocky", "Gas giant", "Rocky", "Gas giant"], "tip": "Inner or outer."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["straight line", "fly off", "move away"], ["no force", "not pulled", "no gravity"]], "tips": ["What keeps it curving?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["Spring tide", "Neap tide", "Spring tide"], "tip": "Pulls adding or not."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["two bulges", "bulge"], ["spin", "rotat"]], "tips": ["Bulges and spinning."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Solar eclipse", "Lunar eclipse", "Lunar eclipse", "Solar eclipse"], "tip": "Whose shadow?"}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["tilt", "angle", "not in a line", "above or below"], ["shadow", "misses", "line up"]], "tips": ["The orbit is tilted."]}]}, "models": {"1": [["Q1", "Mars and Venus rocky; Jupiter and Neptune gas giants."]], "2": [["Q2", "The Earth would move off in a straight line [1] because no force would pull it towards the Sun [1]."]], "3": [["Q3", "Spring; neap; spring."], ["Q4", "There are two bulges of water, one facing the Moon and one opposite [1]; the Earth spins once a day, so each place passes through both [1]."]], "4": [["Q5", "Solar; lunar; lunar; solar."]], "5": [["Q6", "The Moon''s orbit is tilted compared with the Earth''s orbit [1], so most months its shadow passes above or below the Earth and they do not line up exactly [1]."], ["Q7", "Solar: Sun – Moon – Earth, Moon''s shadow on Earth. Lunar: Sun – Earth – Moon, Earth''s shadow on the Moon."]], "6": [["Exit ticket", "Gravity (from the Sun)."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q5_0": "Q6", "q5_1": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Rocky planet or gas giant?", "Q2": "Explain what would happen to the Earth if the Sun''s gravity suddenly disappeared.", "Q3": "Spring tide or neap tide?", "Q4": "Explain why there are two high tides each day.", "Q5": "Solar or lunar eclipse?", "Q6": "Explain why we do not see a solar eclipse every month, even though the Moon orbits the Earth every month.", "Q7": "In your book, draw labelled diagrams of the Sun, Earth and Moon during a solar eclipse and a lunar eclipse. Shade the shadows."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
