insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-MATHS-L1', 'Unit 1 Integers, powers and roots: Integers, factors and roots', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["5", "−5", "8", "−2", "−10"], "tip": "Number line."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 1, "pts": [["19"]], "tips": ["12 − (−7)."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 5, "n": 5, "ans": ["12", "−18", "4", "−3", "−10"], "tip": "Signs rule."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["6", "12", "8", "30"], "tip": "List factors or multiples."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["18", "1 + 3 + 8 + 6", "digit sum", "1+3+8+6"], ["yes"]], "tips": ["Digit sum."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["49", "7", "64", "4", "125"], "tip": "Powers and roots."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 2, "pts": [["lcm", "6, 12, 18, 24", "multiples"], ["24"]], "tips": ["LCM."]}]}, "models": {"1": [["Q1", "5; −5; 8; −2; −10."], ["Q2", "12 − (−7) = 19 °C [1]."]], "2": [["Q3", "12; −18; 4; −3; −10."]], "3": [["Q4", "6; 12; 8; 30."], ["Q5", "Digit sum 1 + 3 + 8 + 6 = 18 [1], which is divisible by 9, so yes [1]."]], "4": [["Q6", "49; 7; 64; 4; 125."]], "5": [["Q7", "Find the LCM of 6 and 8 by listing multiples [1]; 24 seconds [1]."]], "6": [["Exit ticket", "20."]]}, "labels": {"q1_1": "Q2", "q3_1": "Q5", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate.", "Q2": "The temperature is −7 °C at night and 12 °C in the day. Find the difference.", "Q3": "Calculate.", "Q4": "Find.", "Q5": "Use a divisibility test to decide whether 1 386 is divisible by 9. Explain.", "Q6": "Find.", "Q7": "One light flashes every 6 seconds and another every 8 seconds. They flash together now. After how many seconds will they next flash together?"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
