insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-MATHS-L2', 'Unit 2 Place value and rounding: Powers of ten and decimal places', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["345", "72", "6.8", "4 500"], "tip": "Move digits left."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["0.56", "0.0032", "4.7", "0.08"], "tip": "Move digits right."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["2 500 m", "4.5 g", "0.75 litres", "360 cm"], "tip": "× or ÷."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 4, "n": 4, "ans": ["3.5", "9.58", "0.305", "12.0"], "tip": "Look at the next digit."}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 1, "pts": [["decimal place", "1 d.p.", "shows", "accuracy"]], "tips": ["Show the 1 d.p."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["0.35", "0.35"], ["35"]], "tips": ["÷ 1000, × 100."]}]}, "models": {"1": [["Q1", "345; 72; 6.8; 4500."]], "2": [["Q2", "0.56; 0.0032; 4.7; 0.08."]], "3": [["Q3", "2500 m; 4.5 g; 0.75 l; 360 cm."]], "4": [["Q4", "3.5; 9.58; 0.305; 12.0."], ["Q5", "The 0 shows the answer is given to 1 decimal place [1]."]], "5": [["Q6", "$350 ÷ 1000 = $0.35 [1]; $0.35 × 100 = $35 [1]."]], "6": [["Exit ticket", "600."]]}, "labels": {"q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate.", "Q2": "Calculate.", "Q3": "Convert.", "Q4": "Round.", "Q5": "Explain why 11.96 rounded to 1 decimal place is written as 12.0 and not 12.", "Q6": "A shop buys 1 000 pens for $350. Find the cost of one pen, then the cost of 100 pens."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
