insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-MATHS-L3', 'Unit 3 Fractions, decimals and percentages: Three ways to write a part of a whole', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["0.75", "20%", "0.1", "3/5"], "tip": "Learn key facts."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["3 5/6", "2/5", "1 1/2", "70"], "tip": "Common denominators; multiply by the reciprocal."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["12", "15", "36", "40%"], "tip": "Build from 10%."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["9"], ["36"]], "tips": ["20% then subtract."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["1.6", "−2.5", "14.4", "2.8"], "tip": "Line up the decimal point."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["0.625", "0.6"], ["0.58, 3/5, 5/8", "0.58 3/5 5/8"]], "tips": ["Convert to decimals."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 2, "pts": [["85", "0.85"], ["amani"]], "tips": ["Convert to percentages."]}]}, "models": {"1": [["Q1", "0.75; 20%; 0.1; 3/5."]], "2": [["Q2", "3 5/6; 2/5; 1 1/2; 70."]], "3": [["Q3", "12; 15; 36; 40%."], ["Q4", "20% of 45 = $9 [1]; 45 − 9 = $36 [1]."]], "4": [["Q5", "1.6; −2.5; 14.4; 2.8."], ["Q6", "3/5 = 0.6, 5/8 = 0.625 [1]; 0.58, 3/5, 5/8 [1]."]], "5": [["Q7", "17/20 = 85%, Baraka 82%, Chebet 84% [1]; Amani did best [1]."]], "6": [["Exit ticket", "75%."]]}, "labels": {"q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Match the equivalent.", "Q2": "Calculate.", "Q3": "Calculate.", "Q4": "A $45 shirt is reduced by 20%. Find the sale price.", "Q5": "Calculate.", "Q6": "Order, smallest first: 0.58, 5/8, 3/5. Show your working.", "Q7": "Amani scored 17/20, Baraka 0.82 and Chebet 84%. Who did best? Show your working."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
