insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-MATHS-L5', 'Unit 5 Expressions, formulae and equations: Using letters to solve problems', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["6a", "7x + 2y", "6y", "5p − 1"], "tip": "Collect like terms."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["3x + 12", "10y − 5", "a² + 3a", "6x + 6"], "tip": "Multiply each term."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["n + 5", "2m − 3", "4(p + 1)", "x/2"], "tip": "Order of operations."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 1, "pts": [["21"]], "tips": ["Substitute."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["5", "7", "8", "3"], "tip": "Inverse operations."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["2k + 3 = 19", "2k+3=19", "2k = 16"], ["8"]], "tips": ["Set up the equation."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 2, "pts": [["3n + 7 = 34", "3x + 7 = 34", "3n+7=34", "3x+7=34"], ["9"]], "tips": ["Let the number be n."]}]}, "models": {"1": [["Q1", "6a; 7x + 2y; 6y; 5p − 1."]], "2": [["Q2", "3x + 12; 10y − 5; a² + 3a; 6x + 6."]], "3": [["Q3", "n + 5; 2m − 3; 4(p + 1); x/2."], ["Q4", "2 × 9 + 3 = $21 [1]."]], "4": [["Q5", "5; 7; 8; 3."], ["Q6", "2k + 3 = 19 so 2k = 16 [1]; k = 8 km [1]."]], "5": [["Q7", "3n + 7 = 34 [1]; n = 9 [1]."]], "6": [["Exit ticket", "4a − 8."]]}, "labels": {"q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Simplify.", "Q2": "Expand.", "Q3": "Write an expression.", "Q4": "Use C = 2k + 3 to find the fare for 9 km.", "Q5": "Solve.", "Q6": "The taxi fare was $19. Use C = 2k + 3 to form and solve an equation for k.", "Q7": "I think of a number, multiply it by 3 and add 7. The answer is 34. Form and solve an equation to find the number."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
