insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-MATHS-L6', 'Unit 6 Sequences, functions and graphs: Patterns, rules and straight lines', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["21", "48", "32", "81"], "tip": "Find the rule."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["301", "23", "15", "96"], "tip": "Substitute n."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["3n + 1", "3n+1"], ["151"]], "tips": ["Difference 3."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["23"], ["6"]], "tips": ["Forwards, backwards."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Vertical", "Horizontal", "Sloping", "Sloping"], "tip": "x = … is vertical."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 1, "pts": [["2, 3, 4, 5", "2 3 4 5", "2,3,4,5"]], "tips": ["Add 2."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 2, "pts": [["straight", "line", "origin"], ["35"]], "tips": ["5 litres per minute."]}]}, "models": {"1": [["Q1", "21; 48; 32; 81."]], "2": [["Q2", "301; 23; 15; 96."], ["Q3", "nth term 3n + 1 [1]; 3 × 50 + 1 = 151 [1]."]], "3": [["Q4", "6 × 4 − 1 = 23 [1]; (23 + 1) ÷ 4 = 6 [1]."]], "4": [["Q5", "Vertical; horizontal; sloping; sloping."], ["Q6", "2, 3, 4, 5 [1]."]], "5": [["Q7", "A straight line through the origin [1]; 5 litres per minute × 7 = 35 litres [1]."]], "6": [["Exit ticket", "23."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Next term?", "Q2": "Find the term.", "Q3": "Matchstick squares use 4, 7, 10, 13 … matches. Find the nth term and the number of matches for 50 squares.", "Q4": "Function: × 4 then − 1. Find the output for input 6 and the input for output 23.", "Q5": "Vertical, horizontal or sloping?", "Q6": "Complete the table for y = x + 2 for x = 0, 1, 2, 3.", "Q7": "A tank fills at a steady rate: after 2 minutes it holds 10 litres, after 4 minutes 20 litres. Describe the graph of volume against time and find the volume after 7 minutes."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
