insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-MATHS-L7', 'Unit 7 Shapes, area, volume and angles: Measuring shapes and space', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Radius", "Diameter", "Chord", "Tangent"], "tip": "Learn the words."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["24 cm²", "15 cm²", "3 hectares", "42 m²"], "tip": "Formulae."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 1, "pts": [["3"]], "tips": ["l × w × h."]}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["20, 10, 8", "20 + 10 + 8", "38"], ["76"]], "tips": ["Three pairs of faces."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["110°", "95°", "140°", "60°"], "tip": "Angle sums."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["two triangles", "diagonal", "split"], ["180", "2 × 180"]], "tips": ["Draw a diagonal."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["24", "6"], ["30"], ["360"]], "tips": ["Split, add, multiply."]}]}, "models": {"1": [["Q1", "Radius; diameter; chord; tangent."]], "2": [["Q2", "24; 15; 3 ha; 30 + 12 = 42."]], "3": [["Q3", "2 × 1.5 × 1 = 3 m³ [1]."], ["Q4", "2 × (5×4 + 5×2 + 4×2) = 2 × 38 [1] = 76 cm² [1]."]], "4": [["Q5", "360 − 250 = 110; 360 − 265 = 95; 140; 60."], ["Q6", "A diagonal splits a quadrilateral into two triangles [1], and 2 × 180° = 360° [1]."]], "5": [["Q7", "Areas 24 m² and 6 m² [1]; total 30 m² [1]; 30 × 12 = $360 [1]."]], "6": [["Exit ticket", "½ × base × height."]]}, "labels": {"q3_0": "Q3", "q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Name the part of the circle.", "Q2": "Find the area.", "Q3": "A water tank is a cuboid 2 m long, 1.5 m wide and 1 m high. Find its volume.", "Q4": "Find the surface area of a cuboid 5 cm × 4 cm × 2 cm.", "Q5": "Find the missing angle.", "Q6": "Explain why the angles in a quadrilateral add up to 360°.", "Q7": "An L-shaped room is made of a 6 m × 4 m rectangle and a 3 m × 2 m rectangle. Carpet costs $12 per m². Find the total cost."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
