insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-MATHS-L8', 'Unit 8 Position and transformation: Maps, coordinates and transformations', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["200 km", "75 km", "350 km"], "tip": "Multiply by 50."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["6", "7", "9"], "tip": "Subtract."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["(7, 1)", "(4, −3)", "(−4, 3)"], "tip": "Slide or flip."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 1, "pts": [["(−3, −1)", "(-3, -1)", "(-3,-1)", "(−3,−1)"]], "tips": ["Both signs change."]}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["9"], ["6"]], "tips": ["Multiply each length."]}], "5": [{"kind": "text", "id": "q5_1", "q": "Q7", "max": 2, "pts": [["same shape", "angles equal"], ["different size", "enlarge", "not same size"]], "tips": ["Similar vs congruent."]}]}, "models": {"1": [["Q1", "200; 75; 350 km."]], "2": [["Q2", "6; 7; 9."]], "3": [["Q3", "(7, 1); (4, −3); (−4, 3)."]], "4": [["Q4", "(−3, −1) [1]."], ["Q5", "9 cm [1] by 6 cm [1]."]], "5": [["Q6", "e.g. (2, 1) → (−2, 1) → (−2, −1)."], ["Q7", "They have the same shape (equal angles) [1] but different sizes, one is an enlargement of the other [1]."]], "6": [["Exit ticket", "(5, −2)."]]}, "labels": {"q4_0": "Q4", "q4_1": "Q5", "q5_0": "Q6", "q5_1": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Find the real distance (scale 1 cm : 50 km).", "Q2": "Find the distance.", "Q3": "Find the image of (4, 3).", "Q4": "Rotate the point (3, 1) by 180° about the origin.", "Q5": "A rectangle 3 cm by 2 cm is enlarged by scale factor 3. Find the new length and width.", "Q6": "In your book, draw a simple shape on a coordinate grid and create a pattern by reflecting it in the y-axis, then in the x-axis. Write the coordinates of one vertex after each reflection.", "Q7": "Two shapes are similar but not congruent. Explain what this means."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
