insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-MATHS-L9', 'Unit 9 Statistics: Collecting and displaying data', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["small", "only 5", "too few"], ["friends", "one class", "not random", "biased"]], "tips": ["Size and choice."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Pie chart", "Line graph", "Bar chart", "Dual bar chart"], "tip": "What is being shown?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 1, "pts": [["90"]], "tips": ["Fraction × 360."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["8", "8", "7", "5"], "tip": "Order first: 4, 6, 8, 8, 9."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["median"], ["outlier", "210", "extreme"]], "tips": ["One big value."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["sample", "ask", "survey", "random"], ["time", "minutes", "hours", "record"], ["mean", "median", "compare", "average"]], "tips": ["Collect, calculate, compare."]}]}, "models": {"1": [["Q1", "The sample is too small [1] and only includes his friends from one class, so it is biased [1]."]], "2": [["Q2", "Pie; line graph; bar chart; dual bar chart."], ["Q3", "15/60 × 360 = 90° [1]."]], "3": [["Q4", "Mode 8; median 8; mean 35 ÷ 5 = 7; range 5."]], "4": [["Q5", "The median ($23) [1], because the $210 outlier would make the mean too high [1]."]], "5": [["Q6", "Survey a random sample of students from each year [1]; record the time each spends on homework [1]; compare the mean (or median) and range for the two years [1]."]], "6": [["Exit ticket", "13."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Juma asks 5 friends in his class how they travel to school. Give two reasons why his results may not represent the whole school.", "Q2": "Best chart?", "Q3": "In a pie chart of 60 students, 15 walk. Calculate the angle for \"walk\".", "Q4": "For 4, 8, 6, 8, 9 find:", "Q5": "Daily earnings of 5 workers: $20, $22, $23, $25, $210. Which average best represents a typical worker? Explain.", "Q6": "Amina predicts that Year 7 students spend more time on homework than Year 8 students. Describe how she could test this, including the average she would compare."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
