insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS7-MATHS-L10', 'Unit 10 Probability: Introducing probability', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Impossible", "Even chance", "Certain", "Unlikely", "Likely"], "tip": "Use the scale."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["0.7", "3/4", "0.15"], "tip": "1 − P."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["3/10", "1/2", "1/5", "7/10"], "tip": "Count, then divide by 10."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 1, "pts": [["1/2", "3/6", "0.5"]], "tips": ["2, 4, 6."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 1, "pts": [["18/60", "3/10", "0.3"]], "tips": ["Frequency ÷ trials."]}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["not enough", "too few", "more trials", "can''t tell", "cannot tell"], ["10", "small", "repeat", "flip more"]], "tips": ["Is 10 enough?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["3 red", "3"], ["2 blue", "2"], ["1 yellow", "1"]], "tips": ["Out of 6."]}]}, "models": {"1": [["Q1", "Impossible; even chance; certain; unlikely; likely."]], "2": [["Q2", "0.7; 3/4; 0.15."]], "3": [["Q3", "3/10; 1/2; 1/5; 7/10."], ["Q4", "3/6 = 1/2 [1]."]], "4": [["Q5", "18/60 = 0.3 [1]."], ["Q6", "You cannot tell [1] because 10 flips is too few: flip it many more times [1]."]], "5": [["Q7", "3 red [1], 2 blue [1], 1 yellow [1]."]], "6": [["Exit ticket", "0."]]}, "labels": {"q3_1": "Q4", "q4_0": "Q5", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Choose the word.", "Q2": "Find the probability.", "Q3": "Bag: 3 red, 5 blue, 2 green. Find:", "Q4": "A fair dice is rolled. Find P(even number).", "Q5": "A spinner lands on red 18 times in 60 spins. Find the experimental probability of red.", "Q6": "A coin lands heads 7 times in 10 flips. Is it biased? Explain.", "Q7": "Design a spinner with red, blue and yellow sections so that P(red) = 1/2, P(blue) = 1/3 and P(yellow) = 1/6. How many of 6 equal sections should be each colour?"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
